{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    if not nodes or core_distance is None or distances is None:
        raise ValueError("Missing required fields")

    n = len(nodes)

    # Compute mutual reachability: max(core_left, core_right, dist)
    # Canonicalize endpoints so u < v lexicographically
    mr_edges = []
    for edge in distances:
        u, v, d = edge[0], edge[1], edge[2]
        if u > v:
            u, v = v, u
        mr = max(core_distance[u], core_distance[v], d)
        mr_edges.append((mr, u, v))

    # Sort deterministically: by reachability weight, then by node IDs
    mr_edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Kruskal's MST with union-find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for mr, u, v in mr_edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError("Input graph is disconnected; MST cannot span all nodes")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
